#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_A 2
#define GPIO_B 3

void signal_handler(int signum) {
    printf("Program interrupted by signal %d\n", signum);
    gpiod_exit();
    exit(signum != SIGINT ? 0 : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    // Set up signal handler
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    int gpio_a = gpiod_open_phys(GPIO_A);
    if (gpio_a < 0) {
        perror("Failed to open GPIO 2");
        return EXIT_FAILURE;
    }

    int gpio_b = gpiod_open_phys(GPIO_B);
    if (gpio_b < 0) {
        perror("Failed to open GPIO 3");
        gpiod_cleanup(gpio_a);
        return EXIT_FAILURE;
    }

    // Set GPIO_A as output
    if (gpiod_gpio_export(gpio_a, 1) < 0) {
        perror("Failed to export GPIO 2 as output");
        gpiod_close(gpio_a);
        gpiod_close(gpio_b);
        return EXIT_FAILURE;
    }

    // Set GPIO_B as output
    if (gpiod_gpio_export(gpio_b, 1) < 0) {
        perror("Failed to export GPIO 3 as output");
        gpiod_close(gpio_a);
        return EXIT_FAILURE;
    }

    // Toggle GPIO_A and report state
    int state_a = 1;
    while (1) {
        if (gpiod_gpio_write(gpio_a, state_a) < 0) {
            perror("Failed to write to GPIO 2");
            break;
        }

        // Read state of GPIO_B
        int state_b;
        if (gpiod_gpio_read(gpio_b, &state_b) < 0) {
            perror("Failed to read from GPIO 3");
            break;
        }

        printf("GPIO %d: %d\n", GPIO_A, state_b);
        state_a = !state_a; // Toggle state

        // Sleep for 2 seconds
        usleep(2000000);
    }

    // Clean up
    gpiod_gpio_unexport(gpio_a);
    gpiod_gpio_unexport(gpio_b);
    gpiod_cleanup(gpio_a);
    gpiod_cleanup(gpio_b);

    return EXIT_SUCCESS;
}

