#define ADC_CHANNEL 0

int main(int argc, char *argv[]) {
    int file;
    long result;
    struct i2c_client *client;
    uint32_t reg;
    uint16_t value;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <address>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if ((file = open(argv[1], O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(file, 0);
    if (!client) {
        perror("i2c_alloc");
        close(file);
        exit(EXIT_FAILURE);
    }

    result = ioctl(file, I2C_SLAVE, ADS1115_ADDRESS);
    if (result == -1) {
        perror("ioctl");
        i2c_free(client);
        close(file);
        exit(EXIT_FAILURE);
    }

    result = ioctl(file, I2C_MEM_READ, &reg);
    if (result == -1) {
        perror("ioctl");
        i2c_free(client);
        close(file);
        exit(EXIT_FAILURE);
    }

    value = ((uint16_t)result) << 16 | ((uint16_t)(result >> 16));

    while (1) {
        result = ioctl(file, I2C_MEM_READ, &reg);
        if (result == -1) {
            perror("ioctl");
            break;
        }

        value = ((uint16_t)result) << 16 | ((uint16_t)(result >> 16));

        printf("ADC reading: %d\n", value);

        usleep(500000); // 0.5 seconds delay
    }

    i2c_free(client);
    close(file);

    return 0;
}

