#define MLX90614_ADDRESS 0x5A
#define MLX90614_REG_TEMP 0x00

int i2c_fd;

int read_mlx90614_temperature() {
    char command[3] = {0x44, 0x00, 0x00}; // Read register command
    write(i2c_fd, command, 3);

    int buffer[2];
    read(i2c_fd, buffer, 2);

    // Extract temperature from the received data
    unsigned int temp = (buffer[0] << 8) | buffer[1];
    printf("Temperature: %.2f °C\n", temp / 10.0);

    return 0;
}

int main(int argc, char *argv[]) {
    int ret;
    struct i2c_client client;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    client.device = MLX90614_ADDRESS;
    if (ioctl(i2c_fd, I2C_SLAVE, client.device) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = read_mlx90614_temperature();
        if (ret != 0) {
            printf("Error reading temperature\n");
            break;
        }
        usleep(5000000); // 5 seconds delay
    }

    close(i2c_fd);
    return 0;
}

