#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>

#define ADS1115_ADDRESS 0x48
#define ADC_CHANNEL 0

int main(int argc, char *argv[]) {
    int file;
    long long result;
    struct i2c_rdwr_config config;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <i2c-device>\n", argv[0]);
        exit(1);
    }

    file = open(argv[1], O_RDWR);
    if (file == -1) {
        perror("open");
        exit(1);
    }

    memset(&config, 0, sizeof(config));
    config.len = sizeof(config);
    config.flags = I2C_M_BRIGHT;
    config.freq_hz = 100000; // Set I2C frequency to 100kHz

    result = ioctl(file, I2C_RD, &config);
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Write the ADS1115_ADDRESS to the I2C bus
    result = ioctl(file, I2C_WR_SINGLE, ADS1115_ADDRESS);
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Write the register address for ADC configuration
    result = ioctl(file, I2C_WR_SINGLE, 0x40); // ADC configuration register
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Write the ADC channel to the register
    result = ioctl(file, I2C_WR_BYTE, ADC_CHANNEL);
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Start the conversion
    result = ioctl(file, I2C_RD_SINGLE, 0x01); // Start conversion
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Read the 12-bit result
    result = ioctl(file, I2C_RD_BLOCK, 0x00, &result, sizeof(result));
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Convert the raw value to a voltage (assuming 1.8V reference)
    int16_t raw_value = result;
    float voltage = (raw_value * 1.8) / 32768.0;

    printf("Analog Reading: %.3f V\n", voltage);

    // Stop the conversion
    result = ioctl(file, I2C_WR_BYTE, 0x01);
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Read the final result
    result = ioctl(file, I2C_RD_BLOCK, 0x00, &result, sizeof(result));
    if (result < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    // Close the file
    close(file);

    return 0;
}

