#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_PIN 17

int main() {
    int fd;
    gpiod_ctx_t ctx;
    gpiod_result_t res;

    // Initialize libgpiod
    res = gpiod_init(GPIO_DEFAULT_BANK);
    if (res != GPIOD_OK) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Open the GPIO pin
    fd = open("/dev/gpioctl", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/gpioctl");
        return EXIT_FAILURE;
    }

    res = gpiod_request_pin_from_fd(fd, GPIO_PIN, &ctx);
    if (res != GPIOD_OK) {
        perror("Failed to request GPIO pin");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the GPIO pin as output
    res = gpiod_pin_set_direction(ctx, GPIO_PIN, GPIOD_OUTPUT);
    if (res != GPIOD_OK) {
        perror("Failed to set GPIO pin direction");
        gpiod_release_pin(ctx, GPIO_PIN);
        close(fd);
        return EXIT_FAILURE;
    }

    // Toggle the GPIO pin state
    for (int i = 0; i < 1000; i++) {
        res = gpiod_pin_get_value(ctx, GPIO_PIN);
        if (res == GPIOD_OK) {
            if (res == GPIO_INPUT_HIGH) {
                printf("GPIO %d is HIGH\n", GPIO_PIN);
            } else {
                printf("GPIO %d is LOW\n", GPIO_PIN);
            }
        }
        usleep(1000000); // Sleep for 1 second
    }

    // Release the GPIO pin
    res = gpiod_release_pin(ctx, GPIO_PIN);
    if (res != GPIOD_OK) {
        perror("Failed to release GPIO pin");
    }

    // Close the file descriptor
    close(fd);

    // Clean up libgpiod
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

