#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define GPIO_PINS {4, 17, 22, 27}
#define DELAY_SEC 2.0

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t buttons[4];

    ret = gpiod_new_button_array(&ctx, 4, GPIO_PINS);
    if (ret < 0) {
        perror("Failed to create button array");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        buttons[i].pin = GPIO_PINS[i];
        buttons[i].edge = GPIOD_EDGE_RISING;
        buttons[i].pull_up = GPIOD_PULLUP_OFF;
        buttons[i].callback = button_callback;
        ret = gpiod_button_init(&ctx, &buttons[i]);
        if (ret < 0) {
            perror("Failed to initialize button");
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (int i = 0; i < 4; i++) {
            buttons[i].state = gpiod_get_value(&ctx, &buttons[i]);
        }

        for (int i = 0; i < 4; i++) {
            printf("GPIO%d: %d\n", buttons[i].pin + 1, buttons[i].state);
        }

        gpiod_button_del(&ctx, &buttons[0]);
        gpiod_button_del(&ctx, &buttons[1]);
        gpiod_button_del(&ctx, &buttons[2]);
        gpiod_button_del(&ctx, &buttons[3]);

        sleep(DELAY_SEC);
    }

    return EXIT_SUCCESS;
}

void button_callback(gpiod_button_t *button) {
    printf("GPIO%d state changed: %d\n", button->pin + 1, button->state);
}

