#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SI7021_ADDRESS 0x40
#define SI7021_READ_REG 0x0B

int si7021_read_data(int file_descriptor) {
    unsigned char buffer[2];
    int read_bytes;

    read_bytes = read(file_descriptor, buffer, 2);
    if (read_bytes != 2) {
        perror("Failed to read from SI7021");
        return -1;
    }

    // Check for valid response (0x0B, 0x00)
    if (buffer[0] != 0x0B || buffer[1] != 0x00) {
        fprintf(stderr, "Invalid response from SI7021\n");
        return -1;
    }

    return buffer[1];
}

int main(int argc, char *argv[]) {
    int file_descriptor, ret;
    struct i2c_client client;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <i2c device>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    file_descriptor = open(argv[1], O_RDWR | O_LOWDELAY);
    if (file_descriptor < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    memset(&client, 0, sizeof(client));
    client.device = atoi(argv[1]);
    client.address = SI7021_ADDRESS;

    if (ioctl(file_descriptor, I2C_SLAVE, client.address) < 0) {
        perror("Failed to set I2C slave address");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file_descriptor, I2C_MEM_READ, SI7021_READ_REG) < 0) {
        perror("Failed to read from SI7021");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int data = si7021_read_data(file_descriptor);
        if (data == -1) {
            break;
        }

        // Convert SI7021 data to temperature and humidity
        float temperature = (data * 250.0) / 10.0;
        float humidity = (data - 163) * 10.0 / 17.0;

        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);

        usleep(5000000); // Wait for 5 seconds
    }

    close(file_descriptor);
    return 0;
}

#include <stdio.h>
