#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>

#define ADS1115_ADDRESS 0x48
#define ADC_CHANNEL 0

int main() {
    int file;
    long result;
    struct i2c_client *client;
    uint32_t reg;
    uint16_t value;

    // Initialize the ADS1115
    printf("Initializing ADS1115...\n");
    result = ioctl(file, I2C_SLAVE, ADS1115_ADDRESS);
    if (result < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    result = ioctl(file, I2C_MEM_READ, ADS1115_ADDRESS | ADC_CHANNEL);
    if (result < 0) {
        perror("Failed to read from ADS1115");
        exit(EXIT_FAILURE);
    }
    value = ((uint16_t)result >> 16) | ((uint16_t)result & 0xffff);

    printf("Reading from ADC channel %d: %04x\n", ADC_CHANNEL, value);

    // Perform 3 readings, one every second
    for (int i = 0; i < 3; i++) {
        usleep(1000000); // Sleep for 1 second
        result = ioctl(file, I2C_MEM_READ, ADS1115_ADDRESS | ADC_CHANNEL);
        if (result < 0) {
            perror("Failed to read from ADS1115");
            exit(EXIT_FAILURE);
        }
        value = ((uint16_t)result >> 16) | ((uint16_t)result & 0xffff);
        printf("Reading from ADC channel %d: %04x\n", ADC_CHANNEL, value);
    }

    // Release resources
    close(file);
    return EXIT_SUCCESS;
}

