#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define GPIO_PIN_2 2
#define GPIO_PIN_3 3

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, GPIO_PIN_2, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    ret = gpiod_add_event_source(&ctx, GPIOD_DEbounce_ON, button_event, &button);
    if (ret < 0) {
        perror("Failed to add event source");
        gpiod_del(&ctx);
        return EXIT_FAILURE;
    }

    ret = gpiod_enable_edge_detect(&ctx, GPIOD_DEBOUNCE_ON);
    if (ret < 0) {
        perror("Failed to enable edge detection");
        gpiod_del(&ctx);
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_poll(&ctx, 0);
        if (ret < 0) {
            perror("Failed to poll button state");
            break;
        }

        if (button.value) {
            printf("GPIO 2 (GPIO%d) is HIGH\n", GPIO_PIN_2);
            gpiod_remove_event_source(&ctx, GPIOD_DEBOUNCE_ON, &button);
            gpiod_enable_edge_detect(&ctx, GPIOD_DEBOUNCE_OFF);
            gpiod_del(&ctx);
            return EXIT_SUCCESS;
        }

        ret = gpiod_set_edge_detect(&ctx, GPIOD_DEBOUNCE_OFF);
        if (ret < 0) {
            perror("Failed to disable edge detection");
            break;
        }

        ret = gpiod_set_output(&ctx, GPIO_PIN_3);
        if (ret < 0) {
            perror("Failed to set GPIO 3 as output");
            break;
        }

        ret = gpiod_set_level(&ctx, GPIO_PIN_3, 1);
        if (ret < 0) {
            perror("Failed to set GPIO 3 to HIGH");
            break;
        }

        ret = gpiod_poll(&ctx, 0);
        if (ret < 0) {
            perror("Failed to poll button state");
            break;
        }

        if (!button.value) {
            printf("GPIO 3 (GPIO%d) is LOW\n", GPIO_PIN_3);
            gpiod_set_output(&ctx, GPIO_PIN_3, 0);
            gpiod_set_level(&ctx, GPIO_PIN_3, 0);
            gpiod_enable_edge_detect(&ctx, GPIOD_DEBOUNCE_ON);
            gpiod_del(&ctx);
            return EXIT_SUCCESS;
        }

        gpiod_poll(&ctx, 0);
    }

    gpiod_del(&ctx);
    return EXIT_SUCCESS;
}

