#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

#define BAUDRATE B9600
#define BUFSIZE 1024

int main(int argc, char *argv[]) {
    int fd, ret;
    struct termios options, oldoptions;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <serial_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    fd = open(argv[1], O_RDWR | O_NOCTTY | O_NDELAY | O_SYNC);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = tcgetattr(fd, &oldoptions);
    if (ret == -1) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    options = oldoptions;
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFSIZE];
    while (1) {
        ret = read(fd, buffer, BUFSIZE);
        if (ret == -1) {
            perror("read");
            break;
        }
        if (ret == 0) {
            break;
        }

        printf("%s", buffer);
    }

    tcsetattr(fd, TCSANOW, &oldoptions);
    close(fd);

    return 0;
}

