#define GPIO_NUMBER 17

void signal_handler(int signum) {
    gpiod_disable(GPIO_NUMBER);
    printf("Program interrupted by signal\n");
    exit(0);
}

int main() {
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Enable GPIO 17 as an output
    ret = gpiod_gpio_export(GPIO_NUMBER);
    if (ret < 0) {
        perror("Failed to export GPIO 17");
        exit(EXIT_FAILURE);
    }

    // Set initial state (e.g., low)
    ret = gpiod_gpio_set_dir(GPIO_NUMBER, GPIOD_DIR_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO 17 direction");
        exit(EXIT_FAILURE);
    }

    // Toggle state every 0.01 seconds
    while (1) {
        gpiod_gpio_set_level(GPIO_NUMBER, GPIOD_LEVEL_HIGH);
        usleep(100000); // 0.1 seconds

        gpiod_gpio_set_level(GPIO_NUMBER, GPIOD_LEVEL_LOW);
        usleep(100000); // 0.1 seconds
    }

    // Clean up and exit
    gpiod_disable(GPIO_NUMBER);
    gpiod_gpio_free(GPIO_NUMBER);
    return 0;
}

