#include <libgpiod.h>

#define GPIO_PIN_2 2
#define GPIO_PIN_3 3

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, GPIO_PIN_2, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    ret = gpiod_button_init(&button, &ctx);
    if (ret < 0) {
        perror("Failed to initialize button");
        gpiod_destroy_context(&ctx);
        return EXIT_FAILURE;
    }

    ret = gpiod_button_set(&button, GPIOD_INPUT_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set button state");
        gpiod_destroy_button(&button, &ctx);
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_get_value(&button, &ctx);
        if (ret < 0) {
            perror("Failed to read button state");
            break;
        }

        if (ret) {
            printf("GPIO %d is HIGH\n", GPIO_PIN_2);
        } else {
            printf("GPIO %d is LOW\n", GPIO_PIN_2);
        }

        gpiod_button_deinit(&button, &ctx);
        gpiod_context_sleep(&ctx, GPIOD_FOREVER);
    }

    gpiod_destroy_button(&button, &ctx);
    return EXIT_SUCCESS;
}

#include <stdio.h>
