int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_led_t led;

    ret = gpiod_new_output_gpio(&ctx, "GPIO2", 2);
    if (ret < 0) {
        perror("Failed to create GPIO context");
        return EXIT_FAILURE;
    }

    ret = gpiod_led_init(&led, ctx, 3);
    if (ret < 0) {
        perror("Failed to initialize GPIO LED");
        gpiod_ctx_destroy(&ctx);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        ret = gpiod_led_set_value(&led, 1); // Set to high
        printf("Cycle %d: LED ON\n", i+1);
        gpiod_ctx_delay_s(1, &ctx);

        ret = gpiod_led_set_value(&led, 0); // Set to low
        printf("Cycle %d: LED OFF\n", i+1);
        gpiod_ctx_delay_s(1, &ctx);
    }

    gpiod_led_free(&led, &ctx);
    gpiod_ctx_destroy(&ctx);

    return EXIT_SUCCESS;
}

