#include <libgpiod.h>

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_context_init(&ctx);
    if (ret < 0) {
        perror("Failed to initialize gpiod context");
        return EXIT_FAILURE;
    }

    ret = gpiod_button_init(&ctx, GPIO_PIN_4, GPIOD_INPUT, NULL, &button);
    if (ret < 0) {
        perror("Failed to initialize button on GPIO 4");
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    printf("GPIO 4 state: ");
    if (button.value) {
        printf("ON\n");
    } else {
        printf("OFF\n");
    }

    ret = gpiod_button_enable(&ctx, button);
    if (ret < 0) {
        perror("Failed to enable button");
        gpiod_button_disable(&ctx, &button);
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    // Simulate button press
    ret = gpiod_button_trigger(&ctx, button, GPIOD_INPUT_EDGE_RISING);
    if (ret < 0) {
        perror("Failed to trigger button");
        gpiod_button_disable(&ctx, &button);
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    // Simulate button release
    ret = gpiod_button_trigger(&ctx, button, GPIOD_INPUT_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to trigger button");
        gpiod_button_disable(&ctx, &button);
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    gpiod_button_disable(&ctx, &button);

    gpiod_context_destroy(&ctx);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_PIN 17

int main(int argc, char *argv[]) {
    int fd;
    gpiod_context_t ctx;
    gpiod_button_t button;

    // Initialize libgpiod
    if (libgpiod_init(NULL) != 0) {
        perror("libgpiod_init");
        exit(EXIT_FAILURE);
    }

    // Open GPIO 17
    fd = open("/dev/gpioctl", O_RDWR);
    if (fd < 0) {
        perror("open /dev/gpioctl");
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure GPIO 17 as output
    if (ioctl(fd, GPIOD_SET_MODE, GPIO_PIN) < 0) {
        perror("GPIOD_SET_MODE");
        close(fd);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Create a button for GPIO 17
    if (libgpiod_button_init(&button, GPIO_PIN) != 0) {
        perror("libgpiod_button_init");
        close(fd);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Start a loop to toggle the output every 0.5 seconds
    while (1) {
        // Toggle the output state
        if (libgpiod_button_toggle(&button) < 0) {
            perror("libgpiod_button_toggle");
            break;
        }

        // Report the state
        int state = libgpiod_button_get(&button) ? 1 : 0;
        printf("GPIO %d state: %d\n", GPIO_PIN, state);

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up
    libgpiod_button_destroy(&button);
    close(fd);
    libgpiod_cleanup();

    return 0;
}

