#include <libgpiod.h>

#define GPIO_PIN_2 2
#define GPIO_PIN_3 3

int main() {
    int fd;
    gpiod_ctx_t ctx;
    gpiod_result_t ret;

    // Initialize libgpiod
    ret = gpiod_new_context(&ctx);
    if (ret != GPIOD_OK) {
        perror("Failed to create gpiod context");
        exit(EXIT_FAILURE);
    }

    // Open GPIO pins
    ret = gpiod_gpio_export_by_number(&ctx, GPIO_PIN_2, "out");
    if (ret != GPIOD_OK) {
        perror("Failed to export GPIO 2");
        gpiod_ctx_destroy(&ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_gpio_export_by_number(&ctx, GPIO_PIN_3, "out");
    if (ret != GPIOD_OK) {
        perror("Failed to export GPIO 3");
        gpiod_ctx_destroy(&ctx);
        exit(EXIT_FAILURE);
    }

    // Set initial state
    gpiod_gpio_set_level(&ctx, GPIO_PIN_2, GPIOD_OFF);
    gpiod_gpio_set_level(&ctx, GPIO_PIN_3, GPIOD_OFF);

    // Function to toggle GPIO pins
    void toggle_gpio(int pin) {
        gpiod_gpio_set_level(&ctx, pin, !gpiod_gpio_get_level(&ctx, pin));
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Toggle GPIO pins
        toggle_gpio(GPIO_PIN_2);
        toggle_gpio(GPIO_PIN_3);

        // Report state
        printf("Cycle %d: GPIO 2 = %d, GPIO 3 = %d\n", i + 1, gpiod_gpio_get_level(&ctx, GPIO_PIN_2), gpiod_gpio_get_level(&ctx, GPIO_PIN_3));

        // Wait for 5 seconds
        usleep(50000000);
    }

