#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_ADDRESS 0x44
#define OPT3001_REG_STATUS 0x00

int main(int argc, char *argv[]) {
    int file;
    long value;
    u8 reg_val, data_val;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <I2C_BUS>\n", argv[0]);
        exit(1);
    }

    file = open(argv[1], O_RDWR);
    if (file == -1) {
        perror("open");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(file);
        exit(1);
    }

    while (1) {
        value = read(file, &reg_val, 1);
        if (value < 0) {
            perror("read");
            break;
        }

        value = read(file, &data_val, 1);
        if (value < 0) {
            perror("read");
            break;
        }

        // OPT3001 register 0x00 (STATUS) contains the measurement
        printf("Measurement: %lu\n", data_val);
    }

    close(file);
    return 0;
}

