#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define BAUDRATE B9600
#define BUFSIZE 1024

int main(int argc, char *argv[]) {
    int fd, ret;
    struct termios options, oldoptions;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <serial_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    fd = open(argv[1], O_RDWR | O_NOCTTY | O_NDELAY | O_ASYNC);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = tcgetattr(fd, &oldoptions);
    if (ret == -1) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    options = oldoptions;
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFSIZE];
    while (1) {
        ret = read(fd, buffer, BUFSIZE);
        if (ret == -1) {
            perror("read");
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Device is absent or not responding, give up
                printf("Device not found or not responding.\n");
                break;
            }
            exit(EXIT_FAILURE);
        }

        if (ret == 0) {
            // Device has been closed
            printf("Device closed.\n");
            break;
        }

        write(1, buffer, ret);
    }

    tcsetattr(fd, TCSANOW, &oldoptions);
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define GPIO_NUMBER 17

int main(int argc, char *argv[]) {
    int fd;
    gpiod_context_t ctx;
    gpiod_button_t button;

    // Initialize libgpiod
    if (libgpiod_init(NULL) != 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open the GPIO pin
    fd = open(gpio_get_name(GPIO_NUMBER), O_RDWR | O_NOCTTY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_NUMBER, strerror(errno));
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure the button
    gpiod_button_init(&button, fd, GPIO_PIN);

    // Check if the GPIO is present
    if (gpiod_button_get_state(&button) == GPIOD_BUTTON_OFF) {
        fprintf(stderr, "GPIO %d not found, exiting...\n", GPIO_NUMBER);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Set up a timer to toggle the state every 0.01 seconds
    struct itimerspec interval = {0.01, 0};
    struct timespec req, rem;
    clock_gettime(CLOCK_REALTIME, &req);
    req.tv_sec += interval.it_value;
    setitimer(ITIMERSPEC, &interval, &rem);

    while (1) {
        // Toggle the state
        gpiod_button_toggle(&button);

        // Report the state
        int state = gpiod_button_get_state(&button);
        if (state == GPIOD_BUTTON_ON) {
            printf("GPIO %d is ON\n", GPIO_NUMBER);
        } else {
            printf("GPIO %d is OFF\n", GPIO_NUMBER);
        }

        // Sleep until the next interval
        struct timespec t;
        clock_nanosleep(CLOCK_REALTIME, 0, &t, NULL);
    }

    // Clean up and exit
    libgpiod_cleanup();
    return 0;
}

