#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 2

void signal_handler(int signum) {
    gpiod_disable(GPIO_PIN);
    printf("Received signal, exiting.\n");
    exit(0);
}

int main() {
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Enable GPIO 2 as output
    ret = gpiod_gpio_export(GPIO_PIN);
    if (ret < 0) {
        perror("Failed to export GPIO 2");
        exit(EXIT_FAILURE);
    }

    // Set initial state (e.g., low)
    ret = gpiod_gpio_set_dir(GPIO_PIN, GPIOD_DIR_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO 2 direction");
        exit(EXIT_FAILURE);
    }

    // Set initial state (e.g., high)
    ret = gpiod_gpio_set_level(GPIO_PIN, 1);
    if (ret < 0) {
        perror("Failed to set GPIO 2 level");
        exit(EXIT_FAILURE);
    }

    // Run 3 cycles, one every 0.1 seconds
    for (int i = 0; i < 3; i++) {
        // Toggle the state
        ret = gpiod_gpio_set_level(GPIO_PIN, !gpiod_gpio_get_level(GPIO_PIN));
        if (ret < 0) {
            perror("Failed to toggle GPIO 2 state");
            exit(EXIT_FAILURE);
        }

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Disable GPIO 2
    ret = gpiod_gpio_disable(GPIO_PIN);
    if (ret < 0) {
        perror("Failed to disable GPIO 2");
        exit(EXIT_FAILURE);
    }

    // Clean up
    gpiod_cleanup();

    return 0;
}

