#define HTU21D_PRESSURE_MSB 12
#define HTU21D_PRESSURE_LSB 10

typedef struct {
    int fd;
    unsigned char reg;
    unsigned short value;
} htu21d_data;

int read_htu21d(htu21d_data *data) {
    int ret;
    char command[2] = {0x2A, 0x00}; // Read pressure command
    ret = write(data->fd, command, 2);
    if (ret != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    ret = read(data->fd, &data->value, 2);
    if (ret != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    htu21d_data data;
    int fd, ret;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (read_htu21d(&data) < 0) {
        if (errno == ENODEV) {
            printf("HTU21D sensor not found.\n");
            exit(EXIT_FAILURE);
        } else {
            perror("Failed to read from HTU21D sensor");
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    // Check for validity of the reading
    if (data.value & 0x8000) {
        printf("Invalid pressure reading detected.\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Convert pressure to mBar
    data.value = (data.value & 0x7FFF) << 8 | (data.value >> 16) & 0x7FFF;
    float pressure = (float)data.value / 1000.0;

    printf("Pressure: %.2f mBar\n", pressure);

    usleep(60000000); // Wait for 60 seconds

    close(fd);
    return 0;
}

