#define I2C_ADDRESS 0x53
#define BUF_SIZE 6

int main(int argc, char *argv[]) {
    int file;
    long result;
    struct i2c_client *client;
    unsigned char buffer[BUF_SIZE];

    // Initialize the i2c bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    result = ioctl(file, I2C_SLAVE, I2C_ADDRESS);
    if (result == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(file);
    if (!client) {
        perror("i2c_alloc");
        close(file);
        exit(EXIT_FAILURE);
    }

    while (1) {
        result = read(client->handle, buffer, BUF_SIZE);
        if (result == -1) {
            perror("read");
            break;
        }

        // ADXL345 register 0x32 contains the X-axis acceleration data
        unsigned char x_acceleration = buffer[0];
        unsigned char y_acceleration = buffer[1];
        unsigned char z_acceleration = buffer[2];

        printf("X: %d, Y: %d, Z: %d\n", x_acceleration, y_acceleration, z_acceleration);

        usleep(100000); // Wait for 0.1 seconds
    }

    i2c_free(client);
    close(file);
    return 0;
}

