#define TCS34725_ADDRESS 0x20
#define I2C_BUS 1

int read_tcs34725(int file_descriptor, uint8_t *data) {
    int read_bytes;
    read(file_descriptor, data, 6); // Read 6 bytes (address + 3xRGB values)
    if (read_bytes != 6) {
        perror("Failed to read from TCS34725");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int file_descriptor, ret;
    uint8_t r, g, b;

    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(file_descriptor, I2C_SLAVE, TCS34725_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = read_tcs34725(file_descriptor, &r);
        if (ret < 0) {
            perror("Failed to read from TCS34725");
            break;
        }

        ret = read_tcs34725(file_descriptor, &g);
        if (ret < 0) {
            perror("Failed to read from TCS34725");
            break;
        }

        ret = read_tcs34725(file_descriptor, &b);
        if (ret < 0) {
            perror("Failed to read from TCS34725");
            break;
        }

        printf("Red: %d, Green: %d, Blue: %d\n", r, g, b);
        usleep(200000); // 0.2 seconds delay
    }

    close(file_descriptor);
    return 0;
}

