    struct v4l2_pixfmt fmt_pix;
    char filename[256];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output_image>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    snprintf(filename, sizeof(filename), "%s", argv[1]);

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        exit(EXIT_FAILURE);
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.format.code = V4L2_BUF_FORMAT_JPEG;
    fmt.pixelformat.code = V4L2_PIX_FMT_JPEG;
    fmt.fps.n_max = 30;
    fmt.fps.n_value = 30;
    fmt.fps.flag = V4L2_FRAME_FLAG_TOP_FIELD_FIRST;
    fmt.loop = V4L2_LOOP_NONE;

    fmt_pix.pix.format = V4L2_PIX_FMT_JPEG;
    fmt_pix.pix.width = 640;
    fmt_pix.pix.height = 480;
    fmt_pix.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYSTREAMPARAMS, &fmt_pix) < 0) {
        perror("Failed to query stream parameters");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(fd = open(filename, O_WRONLY | O_CREAT | O_EXCL, 0644))) {
        perror("Failed to open output file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &fmt) < 0) {
        perror("Failed to start streaming");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYSTREAMPARAMS, &fmt_pix) < 0) {
        perror("Failed to query stream parameters");
        close(fd);
        exit(EXIT_FAILURE);
    }

    char buffer[1024];
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.data.ptr = buffer;
    buf.bytes_after = 0;
    buf.frame_size = fmt.frame_size;

    for (int i = 0; i < 10; i++) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Failed to dequeue frame");
            break;
        }

        if (write(fd, buffer, fmt.frame_size) != fmt.frame_size) {
            perror("Failed to write frame to file");
            break;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue frame");
            break;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &fmt) < 0) {
        perror("Failed to stop streaming");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
    close(fd);
    ioctl(fd, VIDIOC_S_FMT, &fmt);
    ioctl(fd, VIDIOC_QUERYSTREAMPARAMS, &fmt_pix);
    ioctl(fd, VIDIOC_STREAMOFF, &fmt);
    ioctl(fd, VIDIOC_RELEASE, &fmt);

    return EXIT_SUCCESS;
}

