}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    // Set up signal handler
    sigaction(SIGINT, &sa, NULL);
    sa.sa_flags = SA_RESTART;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Enable GPIO pins
    if (gpiod_pin_config_default(GPIO_PIN_22, GPIOD_OUTPUT) < 0) {
        perror("Failed to configure GPIO 22 as output");
        return EXIT_FAILURE;
    }
    if (gpiod_pin_config_default(GPIO_PIN_27, GPIOD_OUTPUT) < 0) {
        perror("Failed to configure GPIO 27 as output");
        return EXIT_FAILURE;
    }

    // Set initial states
    gpiod_pin_set_dir(GPIO_PIN_22, GPIOD_DIR_OUT);
    gpiod_pin_set_level(GPIO_PIN_22, 0); // Initial state off
    gpiod_pin_set_level(GPIO_PIN_27, 1); // Initial state on

    // Start a timer for periodic state reporting
    struct sigaction sa_timer;
    sa_timer.sa_handler = signal_handler;
    sigaction(SIGALRM, &sa_timer, NULL);
