        perror("Failed to set video format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Create the output file
    sprintf(filename, "/tmp/image_%d.jpg", getpid());
    fd = open(filename, O_WRONLY | O_CREAT | O_EXCL, 0644);
    if (fd < 0) {
        perror("Failed to create output file");
        close(fd);
        exit(EXIT_FAILURE);
