        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set i2c address");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_M_READ) < 0) {
        perror("Failed to read from slave");
        exit(EXIT_FAILURE);
    }

    close(fd);
