    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_M_WRITE) < 0) {
        perror("Failed to write to slave");
        exit(EXIT_FAILURE);
