int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, HC_SR04_GPIO_TRIG, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_get_value(&ctx, &button);
        if (ret < 0) {
            perror("Failed to read button state");
            continue;
        }

        if (button) {
            // Trigger the HC-SR04 ultrasonic sensor
            gpiod_button_release(&ctx);

            // Send a high signal to the trigger pin
            gpiod_output_set_level(&ctx, HC_SR04_GPIO_TRIG, GPIO_OUTPUT_HIGH);

            // Wait for the echo signal
            ret = gpiod_wait_us(10);
            if (ret < 0) {
                perror("Failed to wait for echo");
                continue;
            }

            // Read the echo signal
            ret = gpiod_get_value(&ctx, &button);
            if (ret < 0) {
                perror("Failed to read button state");
                continue;
            }

            if (button) {
                // Measure the time in microseconds
                uint32_t duration = gpiod_get_us(&ctx);

                // Convert duration to centimeters
                float distance = (duration / 2) * 17150;

                // Print the distance
                printf("Distance: %.2f cm\n", distance);
            } else {
                printf("Invalid reading, giving up.\n");
            }

            // Reset the button state
            gpiod_button_release(&ctx);

            // Wait for 0.1 seconds before the next reading
            gpiod_delay_us(100);
        }
    }

    // Release the hardware resources
    gpiod_button_free(&ctx);

    return EXIT_SUCCESS;
}

