        mqtt_client_disconnect(client);
        mqtt_client_destroy(client);
        exit(EXIT_FAILURE);
    }

    // Publish message
    mqtt_ret = mqtt_client_publish(client, NULL, MQTT_TOPIC, strlen(message), (uint8_t *)message, 0);
    if (mqtt_ret != MQTTP_ERR_OK) {
        fprintf(stderr, "MQTT message publishing failed: %s\n", mqtt_strerror(mqtt_ret));
