// Function to handle ADS1115 readings
int read_ads1115(int channel) {
    ads1115_config_t config;
    config.mode = ADS1115_MODE_12BIT;
    config.analog_in = channel;
    config.power_up_time = 0;

    int result = ads1115_init();
    if (result != ADS1115_OK) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        return -1;
    }

    result = ads1115_set_config(&config);
    if (result != ADS1115_OK) {
        fprintf(stderr, "Failed to set ADS1115 configuration\n");
        ads1115_deinit();
        return -1;
    }

    int16_t value = ads1115_read_adc(ADS1115_CHANNEL_0);
    ads1115_deinit();

    return value;
}

