    mqtt_client_handle_t client;
    int channel = 0;

    // Initialize paho-mqtt-c
    mqtt_client_init(&client);
    mqtt_client_on_message(client, on_message_arrived);
    mqtt_client_connect(&client, "mqtt.eclipse.org", 1883, 60);

    // Initialize ADS1115
    int result = read_ads1115(channel);
    if (result == -1) {
        return -1;
    }

