#include <fcntl.h>
#include <errno.h>

#define PORT "/dev/ttyAMA0" // Replace with your UART port

int main(int argc, char *argv[]) {
    int fd;
    struct termios options;

    // Open the serial port
    fd = open(PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set up terminal I/O options
    tcflush(fd, TCIFLUSH);
    tcgetattr(fd, &options);
    options.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcsetattr(fd, TCSANOW, &options);

    // Read data from the serial port
    char buffer[128];
    while (1) {
        int n = read(fd, buffer, sizeof(buffer));
        if (n == -1) {
            perror("read");
            exit(EXIT_FAILURE);
        }
        if (n == 0) {
            break; // End of file
        }

        // Print the received data
        write(1, buffer, n);
    }

    // Close the serial port
    close(fd);

    // Restore terminal I/O options
    tcsetattr(fd, TCSANOW, &options);
    close(fd);

    return 0;
}

