#define MQTT_TOPIC "sensor/readings"
#define NUM_CHANNELS 4

// Function to handle SIGINT (Ctrl+C)
void signal_handler(int signum) {
    printf("Exiting...\n");
    paho_mqtt_disconnect(NULL);
    paho_mqtt_loopback_stop(NULL);
    pigpio_terminate(NULL);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, signal_handler) == SIG_IGN) {
        perror("signal");
        return 1;
    }

    pigpio_init(1); // Initialize pigpio with default pin numbering

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        paho_mqtt_disconnect(NULL);
        paho_mqtt_loopback_stop(NULL);
        pigpio_terminate(NULL);
        return 1;
    }

    int mcp3008_channel[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        mcp3008_channel[i] = 0;
    }

    // Configure MCP3008
    gpioSetMode(MCP3008_CHIPSELECT, PI_OUTPUT);
    gpioWrite(MCP3008_CHIPSELECT, 0);
    gpioSetMode(MCP3008_CHIPSELECT, PI_OUTPUT);
    gpioWrite(MCP3008_CHIPSELECT, 1);

    // Start ADC conversion
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(MCP3008_CHANNEL(i), PI_OUTPUT);
        gpioWrite(MCP3008_CHANNEL(i), 0);
        gpioSetMode(MCP3008_CHANNEL(i), PI_INPUT);
        gpioRead(MCP3008_CHANNEL(i));
        mcp3008_channel[i] = gpioRead(MCP3008_CHANNEL(i));
        gpioWrite(MCP3008_CHANNEL(i), 0);
    }

    // Connect to MQTT broker
    mqttClientHandle_t client;
    mqttHandle_t session;
    mqttClientInit(&client);
    mqttSessionInit(&session, client);

    if (mqttConnect(session, MQTT_BROKER, 1883, 60, NULL) != MQTTP_OK) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mqttSessionDisconnect(session);
        mqttClientDestroy(client);
        return 1;
    }

    if (mqttPublish(session, MQTT_TOPIC, NULL, strlen(MQTT_TOPIC), NULL, 0, 0) != MQTTP_OK) {
        fprintf(stderr, "Failed to publish message\n");
        mqttSessionDisconnect(session);
        mqttClientDestroy(client);
        return 1;
    }

    // Publish sensor readings
    for (int i = 0; i < NUM_CHANNELS; i++) {
        char topic_data[20];
        sprintf(topic_data, "%s/%d", MQTT_TOPIC, i);
        char message[20];
        sprintf(message, "Sensor %d: %d", i, mcp3008_channel[i]);
        if (mqttPublish(session, topic_data, NULL, strlen(topic_data), message, strlen(message), 0) != MQTTP_OK) {
            fprintf(stderr, "Failed to publish message\n");
        }
    }

    // Disconnect from MQTT broker
    mqttDisconnect(session);
    mqttSessionDisconnect(session);
    mqttClientDestroy(client);

    pigpio_terminate(NULL);
    return 0;
}

