    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output_image_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    snprintf(filename, sizeof(filename), "%s/%s", getenv("HOME"), argv[1]);

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.width = IMAGE_WIDTH;
    fmt.height = IMAGE_HEIGHT;
    fmt.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.framerate.num = 30;
    fmt.framerate.den = 1;
    fmt.flags = V4L2_FRAME_FLAG_TOP_FIELD_FIRST;

    if (ioctl(fd, VIDIOC_S_FORMAT, &fmt) < 0) {
        perror("Failed to set camera format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYSTREAMPARAM, &sb) < 0) {
        perror("Failed to query stream parameters");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (sb.st_size == 0) {
        fprintf(stderr, "Camera device is not responding.\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYINTERFACE, (void *) &interface) < 0) {
        perror("Failed to query camera interface");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_S_CONTROL, &control) < 0) {
        perror("Failed to set camera control");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &stream) < 0) {
        perror("Failed to start camera stream");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYSTREAM, &streaminfo) < 0) {
        perror("Failed to query camera stream");
        close(fd);
        exit(EXIT_FAILURE);
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Failed to open output file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    char buffer[1024];
    ssize_t bytes_read;

    while (streaminfo.count > 0) {
        bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("Failed to read from camera");
            fclose(fp);
            close(fd);
            exit(EXIT_FAILURE);
        }

        if (bytes_read == -1 && errno == EAGAIN) {
            continue;
        }

        fwrite(buffer, 1, bytes_read, fp);
        streaminfo.count -= bytes_read;
    }

    fclose(fp);
    close(fd);

    printf("Image saved to %s\n", filename);
    return EXIT_SUCCESS;
}

