#define PCF8574_ADDRESS 0x40
#define PCF8574_REG_STATUS 0x00
#define PCF8574_REG_DATA 0x01

int main() {
    int file;
    struct i2c_client *client;
    gpiopinout_t gpio_pins[8];
    int i;

    // Initialize gpiopinout_t array for GPIO pins
    for (i = 0; i < 8; i++) {
        gpio_pins[i] = gpiopin_get(i);
    }

    // Open I2C bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(file);
    if (!client) {
        perror("i2c_alloc");
        close(file);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins for PCF8574
    // Assuming GPIO pins 23 to 29 are connected to PCF8574 data pins
    for (i = 23; i <= 29; i++) {
        gpiopinmode(i, GPIOPIN_OUTPUT);
    }

    // Write to PCF8574 status register to enable
    write(client, &PCF8574_REG_STATUS, 1);

    // Read data from PCF8574
    for (i = 0; i < 8; i++) {
        write(client, &PCF8574_REG_DATA, 0);
        read(client, &data, 1);
        gpio_pins[i] = data & 0x01;
        printf("Pin %d: %d\n", i + 23, data);
    }

    // Clean up
    i2c_free(client);
    close(file);

    // Release GPIO pins
    for (i = 0; i < 8; i++) {
        gpiopinrelease(gpio_pins[i]);
    }

    return 0;
}

