    // Initialize libgpiod
    if (libgpiod_init(NULL) != 0) {
        perror("libgpiod_init");
        exit(EXIT_FAILURE);
    }

    // Open GPIO 23
    fd = open("/dev/gpioctl", O_RDWR);
    if (fd < 0) {
        perror("open");
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    in_pin = GPIOD_IN0;
    if (libgpiod_gpio_request(fd, GPIO_PIN, &dev) != 0) {
        perror("libgpiod_gpio_request");
        close(fd);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Set up the GPIO pin as input
    if (libgpiod_gpio_direction_input(dev, &in_pin) != 0) {
        perror("libgpiod_gpio_direction_input");
        lseek(fd, 0, SEEK_SET);
        close(fd);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Report the state and loop
    while (1) {
        gpiod_digital_read(dev, &in_pin);
        int state = (in_pin & 0x01) ? 1 : 0;
        printf("GPIO %d state: %d\n", GPIO_PIN, state);
        usleep(5000000); // 5 seconds
    }

    // Clean up and exit
    lseek(fd, 0, SEEK_SET);
    close(fd);
    libgpiod_gpio_free(dev);
    libgpiod_cleanup();

