#define SHT31_I2C_ADDR 0x44
#define SHT31_REG_STATUS 0x00
#define SHT31_REG_HUMIDITY 0x01
#define SHT31_REG_TEMPERATURE 0x02

#define BUFFER_SIZE 2

int main(int argc, char *argv[]) {
    int file;
    long result;
    struct i2c_client *client;
    uint8_t buffer[BUFFER_SIZE];
    uint16_t humidity, temperature;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <delay_seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    try {
        file = open("/dev/i2c-1", O_RDWR);
        if (file == -1) {
            perror("open /dev/i2c-1");
            exit(EXIT_FAILURE);
        }

        result = ioctl(file, I2C_SLAVE, SHT31_I2C_ADDR);
        if (result == -1) {
            perror("ioctl I2C_SLAVE");
            close(file);
            exit(EXIT_FAILURE);
        }

        client = i2c_alloc(file, 0);
        if (!client) {
            perror("i2c_alloc");
            close(file);
            exit(EXIT_FAILURE);
        }

        while (1) {
            result = read(client, buffer, BUFFER_SIZE);
            if (result == -1) {
                perror("read");
                i2c_free(client);
                close(file);
                exit(EXIT_FAILURE);
            }

            if (buffer[0] & 0x02) { // Check for readiness flag
                if (read(client, &humidity, 2) != 2 || buffer[1] & 0x02) {
                    fprintf(stderr, "Invalid SHT31 reading\n");
                    i2c_free(client);
                    close(file);
                    exit(EXIT_FAILURE);
                }

                if (read(client, &temperature, 2) != 2 || buffer[1] & 0x02) {
                    fprintf(stderr, "Invalid SHT31 reading\n");
                    i2c_free(client);
                    close(file);
                    exit(EXIT_FAILURE);
                }

                printf("Humidity: %.2f%%\tTemperature: %.1f°C\n", (float)humidity / 10.0, (float)temperature / 10.0);
            }

            usleep(1000000 * atoi(argv[1])); // Delay for specified seconds
        }
    } catch (const char* msg) {
        fprintf(stderr, "Error: %s\n", msg);
        exit(EXIT_FAILURE);
    } finally {
        i2c_free(client);
        close(file);
    }

    return EXIT_SUCCESS;
}

