static int dev_open(struct v4l2_device *dev, int flags, int cmd)
{
    int fd = fileno(dev);
    if (fd < 0)
        return -EBADF;

    if (ioctl(fd, VIDIOC_QUERYSTREAMPARAMS, (unsigned long *)NULL) < 0)
        return -EIO;

    return fd;
}

static int dev_release(struct v4l2_device *dev)
{
    int fd = fileno(dev);
    if (fd < 0)
        return -EBADF;

    close(fd);
    return 0;
}

static int dev_ioctl(struct v4l2_device *dev, unsigned long cmd, unsigned long arg)
{
    int fd = fileno(dev);
    if (fd < 0)
        return -EBADF;

    switch (cmd) {
        case VIDIOC_S_FRAMESIZE:
            if (arg & V4L2_FRAMESIZE_YUYV)
                ioctl(fd, VIDIOC_S_FRAMESIZE, (unsigned long)FRAMESIZE);
            else
                return -EOPNOTSUPP;
        default:
            return -ENOTSUP;
    }
}

static int dev_get_format(struct v4l2_device *dev, unsigned long *format)
{
    int fd = fileno(dev);
    if (fd < 0)
        return -EBADF;

    if (ioctl(fd, VIDIOC_QUERYVIDEOFORMAT, format) < 0)
        return -EIO;

    return 0;
}

