    fmt.height = 1080;
    fmt.field = V4L2_FIELD_INTERLACE_NONE;
    fmt.flags = V4L2_BUF_TYPE_VIDEO_CAPTURE | V4L2_BUF_TYPE_VIDEO_OUTPUT;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        close(fd);
        perror("Failed to set format");
        return -1;
    }

    unsigned char *buffer = malloc(FRAMESIZE);
    if (!buffer) {
        close(fd);
        perror("Failed to allocate memory");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.data.ptr = buffer;
    buf.length = FRAMESIZE;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        free(buffer);
        close(fd);
        perror("Failed to query buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        free(buffer);
        close(fd);
        perror("Failed to start streaming");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        free(buffer);
        close(fd);
        perror("Failed to dispatch buffer");
        return -1;
    }

    close(fd);

    // Save the image to a file
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        free(buffer);
        return -1;
    }

    fwrite(buffer, 1, FRAMESIZE, file);
    fclose(file);

    free(buffer);
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output_image_file>\n", argv[0]);
        return 1;
    }

    if (!module_exists(NULL, DEVICE_NAME)) {
        fprintf(stderr, "Camera device not found.\n");
        return 1;
    }

    const char *filename = argv[1];
    capture_image(filename);

    return 0;
}

