#include <pigpio.h>

#define GPIO 18
#define CYCLES 3
#define DELAY_SEC 0.005

int main(int argc, char *argv[]) {
    int gpio = GPIO;
    int cycles = CYCLES;
    double delay_ms = DELAY_SEC * 1000;

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "pigpioInitialise() failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < cycles; i++) {
        for (int j = 0; j < 10; j++) { // Assuming 10 pixels per cycle
            setPixelColour(gpio, j % 256, j % 256, j % 256); // Red, Green, Blue, Alpha
            usleep(delay_ms);
        }
    }

    pigpioTerminate(1000); // Terminate pigpio with a timeout of 1 second

    printf("Program completed.\n");
    return EXIT_SUCCESS;
}

void setPixelColour(int gpio, int r, int g, int b) {
    if (pigpioSetMode(gpio, PIGPIO_OUTPUT) < 0) {
        fprintf(stderr, "pigpioSetMode() failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (pigpioWrite(gpio, r, g, b) < 0) {
        fprintf(stderr, "pigpioWrite() failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 27

void signal_handler(int signum) {
    printf("Program received interrupt signal, exiting gracefully.\n");
    gpiod_disable(GPIO_PIN);
    exit(0);
}

int main() {
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Enable GPIO 27 as an output
    ret = gpiod_pin_config_init(GPIO_PIN, GPIOD_OUTPUT);
    if (ret < 0) {
        perror("Failed to configure GPIO 27 as output");
        exit(EXIT_FAILURE);
    }

    // Enable the pin
    ret = gpiod_pin_enable(GPIO_PIN);
    if (ret < 0) {
        perror("Failed to enable GPIO 27");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read the state of the GPIO
        int state = gpiod_get_value(GPIO_PIN);

        // Check if the reading is valid
        if (state == -1) {
            perror("Failed to read GPIO state");
            continue;
        }

        printf("Current state of GPIO %d: %d\n", GPIO_PIN, state);

        // Wait for 2 seconds before the next iteration
        usleep(2000000);
    }

    // Disable the pin and release resources
    gpiod_pin_disable(GPIO_PIN);
    gpiod_pin_config_free(GPIO_PIN);
    gpiod_disable();

    return 0;
}

