    char buffer[32];
    int i;

    // Initialize the w1 thermal sensor
    fd = open("/sys/class/hwmon/hwmon0/device/w1_slave", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /sys/class/hwmon/hwmon0/device/w1_slave");
        exit(EXIT_FAILURE);
    }

    // Read the temperature
    slave = w1->instance(fd);
    for (i = 0; i < 3; i++) {
        if (w1_read_u8_mem(slave, &buffer) != 16) {
            perror("Failed to read from the device");
            exit(EXIT_FAILURE);
        }

        // Convert the raw data to a temperature in Celsius
        int16_t temperature = (buffer[0] << 8) | buffer[1];
        float celsius = (temperature * 0.01) - 50; // Convert to Celsius

        printf("Temperature: %.1f°C\n", celsius);
        usleep(5000000 * (i + 1)); // 5 seconds delay
    }

    // Close the file descriptor
    close(fd);

    return EXIT_SUCCESS;
}

