#include <libgpiod.h>
#include <unistd.h>

#define HC_SR04_ECHO_PIN 24
#define HC_SR04_TRIG_PIN 18
#define HC_SR04_SCLK_PIN 23

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, HC_SR04_TRIG_PIN, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    gpiod_button_init(&button, ret);

    while (1) {
        ret = gpiod_get_value(&button);
        if (ret < 0) {
            perror("Failed to read button state");
            break;
        }

        if (ret) {
            // Trigger is high, send trigger pulse
            gpiod_button_release(&button);
            usleep(100000); // 100ms trigger pulse

            // Read echo pin
            ret = gpiod_get_value(&button);
            if (ret < 0) {
                perror("Failed to read button state");
                break;
            }

            if (ret) {
                // Echo pin is high, calculate distance
                int duration = gpiod_get_duration(&button);
                double time_in_us = duration * sysconf(_SC_CLK_PER_SEC);
                double distance = time_in_us / 2 * 17150; // Conversion factor from us to cm

                printf("Distance: %.2f cm\n", distance);
            } else {
                printf("No response from HC-SR04, exiting.\n");
                break;
            }
        }

        usleep(100000); // Sleep for 100ms before next measurement
    }

    gpiod_button_destroy(&button);
    return EXIT_SUCCESS;
}

