    int fd;
    gpiod_context_t ctx;
    gpiod_button_t button;

    // Initialize libgpiod
    if (libgpiod_init(NULL) != 0) {
        perror("libgpiod_init");
        return EXIT_FAILURE;
    }

    // Open GPIO 2
    fd = open("/dev/gpioctl", O_RDWR);
    if (fd < 0) {
        perror("open /dev/gpioctl");
        libgpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Configure GPIO 2 as output
    if (ioctl(fd, GPIOD_SET_MODE, GPIO_PIN) < 0) {
        perror("GPIOD_SET_MODE");
        close(fd);
        libgpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Create a button for GPIO 2
    if (libgpiod_button_new(&button, GPIO_PIN) < 0) {
        perror("libgpiod_button_new");
        close(fd);
        libgpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Start reading the button state
    if (libgpiod_button_start(&button) < 0) {
        perror("libgpiod_button_start");
        libgpiod_button_free(&button);
        close(fd);
        libgpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read the button state
        int state = lgpio_button_get(&button);

        // Check if the state is valid
        if (state == -1) {
            fprintf(stderr, "Error reading button state\n");
            continue;
        }

        // Print the state
        printf("GPIO 2 state: %d\n", state);

        // Wait for 5 seconds
        usleep(50000000);
    }

    // Stop reading the button
    lgpio_button_stop(&button);

    // Close the file descriptor
    close(fd);

    // Clean up
    libgpiod_button_free(&button);
    libgpiod_cleanup();

    return EXIT_SUCCESS;
}

