#define GPIO_PINS {4, 17, 18}
#define DELAY_SEC 0.1

int main(int argc, char *argv[]) {
    int gpioPins[3];
    int i;
    char state[10];

    // Initialize pigpio library
    if (piGPIOInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    // Set GPIO pins as output
    for (i = 0; i < 3; i++) {
        gpioPins[i] = GPIO_PINS[i];
        if (piGPIOsetmode(gpioPins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output.\n", gpioPins[i]);
            piGPIOExit();
            return EXIT_FAILURE;
        }
    }

    while (1) {
        // Generate PWM signal
        for (i = 0; i < 3; i++) {
            piGPIOsetdutycycle(gpioPins[i], 100); // 100% duty cycle
            usleep(100000 * 10); // 100ms delay
            piGPIOsetdutycycle(gpioPins[i], 0); // 0% duty cycle
            usleep(100000 * 10);
        }

        // Report the state
        for (i = 0; i < 3; i++) {
            piGPIOget(gpioPins[i]);
            sprintf(state, "GPIO %d: %d\n", gpioPins[i], piGPIOget(gpioPins[i]));
            printf("%s", state);
        }

        // Check for interrupt
        if (piGPIOcheckerror() != PI_OK) {
            fprintf(stderr, "Error: %s\n", piGPIOstrerror(piGPIOgeterror()));
            break;
        }

        // Sleep before next cycle
        usleep(100000 * DELAY_SEC);
    }

    // Clean up and exit
    piGPIOExit();
    return EXIT_SUCCESS;
}

