        printf("Cycle %d: PWM state: ON\n", i);
        pigpio_write(4, 100); // Set PWM to 100%
        usleep(DELAY_SECONDS * 1000000); // Sleep for 60 seconds
    }

    // Stop PWM and release resources
    pigpio_stop();

    // Clean up
    for (int pin : GPIO_PINS) {
        pigpio_cleanup(pin);
    }

