    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, HC_SR04_GPIO_TRIGGER, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    gpiod_button_init(&button, &ctx);

    ret = gpiod_button_set(&button, GPIOD_INPUT_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set button state");
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_get_value(&button, &ret);
        if (ret < 0) {
            perror("Failed to get button state");
            return EXIT_FAILURE;
        }

        if (ret) {
            // Button pressed, perform HC-SR04 measurement
            unsigned long start_time, end_time;
            uint32_t duration;

            // Initialize GPIO for HC-SR04
            ret = gpiod_pin_configure(HC_SR04_GPIO_TRIGGER, GPIOD_OUTPUT);
            if (ret < 0) {
                perror("Failed to configure GPIO for trigger");
                return EXIT_FAILURE;
            }

            ret = gpiod_pin_configure(HC_SR04_GPIO_ECHO, GPIOD_OUTPUT);
            if (ret < 0) {
                perror("Failed to configure GPIO for echo");
                return EXIT_FAILURE;
            }

            // Send high pulse to trigger HC-SR04
            gpiod_pin_set_level(HC_SR04_GPIO_TRIGGER, GPIOD_HIGH);
            start_time = gpiod_get_time();

            // Wait for echo
            gpiod_wait_us(10);

            // Send low pulse to HC-SR04
            gpiod_pin_set_level(HC_SR04_GPIO_TRIGGER, GPIOD_LOW);

            // Read echo
            ret = gpiod_get_value(&button, &ret);
            if (ret < 0) {
                perror("Failed to read button state");
                return EXIT_FAILURE;
            }

            if (ret) {
                end_time = gpiod_get_time();
                duration = (end_time - start_time) * 1000; // Convert to microseconds

                printf("Distance: %lu micrometers\n", duration);
            } else {
                printf("HC-SR04 not responding\n");
            }

            // Release GPIO for HC-SR04
            gpiod_pin_configure(HC_SR04_GPIO_TRIGGER, GPIOD_INPUT);
            gpiod_pin_configure(HC_SR04_GPIO_ECHO, GPIOD_INPUT);
        }

