#define BMP280_REG_PRESSURE 0x1A

int main() {
    int file;
    long result;
    struct i2c_client *client;
    uint8_t buffer[6];

    // Initialize i2c-dev
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    result = ioctl(file, I2C_SLAVE, BMP280_ADDRESS);
    if (result < 0) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(file);
    if (!client) {
        perror("i2c_alloc");
        close(file);
        exit(EXIT_FAILURE);
    }

    // Read BMP280 pressure register
    result = read(client, buffer, sizeof(buffer));
    if (result < 0) {
        perror("read");
        i2c_free(client);
        close(file);
        exit(EXIT_FAILURE);
    }

    if (result == 0) {
        printf("BMP280 not found!\n");
        i2c_free(client);
        close(file);
        exit(EXIT_FAILURE);
    }

    // Convert 16-bit value to 12-bit pressure
    uint16_t pressure = (buffer[2] << 8) | buffer[3];
    float p = (pressure * 0.019) / 1000.0; // Convert to hPa

    for (int i = 0; i < 3; i++) {
