#define BAUDRATE B9600
#define BUFSIZE 1024

int main(int argc, char *argv[]) {
    int fd, ret;
    struct termios options, oldoptions;
    char buffer[BUFSIZE];
    unsigned char data;

    fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = tcgetattr(fd, &oldoptions);
    if (ret == -1) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    options = oldoptions;
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    ret = tcsetattr(fd, TCSANOW, &options);
    if (ret == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = read(fd, &data, 1);
        if (ret == -1) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        if (data == '\n' || data == '\r') {
            printf("%c", data);
            fflush(stdout);
        }

        if (ret == 0) {
            if (feof(stdin)) {
                printf("Device not present, exiting...\n");
                exit(EXIT_SUCCESS);
            } else {
                printf("Device does not respond, exiting...\n");
                exit(EXIT_SUCCESS);
            }
        }

        write(fd, &data, 1);
    }

    tcsetattr(fd, TCSANOW, &oldoptions);
    close(fd);
    return 0;
}

