    ret = gpiod_output_set_level(GPIO_PIN, 0);
    if (ret < 0) {
        perror("Failed to set initial state");
        exit(EXIT_FAILURE);
    }

    // Set up a signal handler to cleanly exit on SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to toggle state every 0.001 seconds
    while (1) {
        gpiod_event event;
        ret = gpiod_poll(GPIO_PIN, &event, 0, 0.001);
        if (ret < 0) {
            perror("Failed to poll GPIO state");
            break;
        }

        if (event.value & GPIOD_EVENT_SET) {
            printf("Current state: HIGH\n");
            ret = gpiod_output_set_level(GPIO_PIN, 1);
        } else {
            printf("Current state: LOW\n");
            ret = gpiod_output_set_level(GPIO_PIN, 0);
        }
    }

