#define ADXL345_YOUT_L_REG 0x35
#define ADXL345_ZOUT_H_REG 0x36
#define ADXL345_ZOUT_L_REG 0x37

int main(int argc, char *argv[]) {
    int file;
    long long value;
    uint8_t reg_address, reg_data[2];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <address>\n", argv[0]);
        exit(1);
    }

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, atoi(reg_address)) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file);
