    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins
    if (gpiod_gpio_set_mode(gpio_handle_trigger, GPIOD_MODE_OUTPUT) < 0) {
        perror("Failed to set GPIO 4 as output");
        exit(EXIT_FAILURE);
    }
    if (gpiod_gpio_set_mode(gpio_handle_echo, GPIOD_MODE_INPUT) < 0) {
        perror("Failed to set GPIO 18 as input");
        exit(EXIT_FAILURE);
    }

    if (gpiod_gpio_request_pin_all(gpio_handle_trigger, 1) < 0) {
        perror("Failed to request GPIO 4");
        exit(EXIT_FAILURE);
    }
    if (gpiod_gpio_request_pin_all(gpio_handle_echo, 1) < 0) {
        perror("Failed to request GPIO 18");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    if (gpiod_gpio_set_drive_level(gpio_handle_trigger, 1) < 0) {
        perror("Failed to set GPIO 4 high");
        exit(EXIT_FAILURE);
    }
    if (gpiod_gpio_set_drive_level(gpio_handle_echo, 0) < 0) {
        perror("Failed to set GPIO 18 low");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Send pulse and measure echo
        gpiod_gpio_set_value(gpio_handle_trigger, 0);
        usleep(50000); // Pulse duration (50 microseconds)
        gpiod_gpio_set_value(gpio_handle_trigger, 1);
        usleep(50000); // Pulse duration (50 microseconds)

        gpiod_gpio_get_level(gpio_handle_echo, &echo_level);

        if (echo_level) {
            int duration = gpiod_get_timer_count(gpio_handle_echo);
            double time_taken = (duration * 5) / 29; // Convert to cm
            printf("Distance: %.2f cm\n", time_taken);
        } else {
            printf("No echo received, device may not be connected or responding.\n");
        }

        usleep(100000); // Delay between readings
    }

    // Release GPIO resources
    gpiod_gpio_free(gpio_handle_trigger);
    gpiod_gpio_free(gpio_handle_echo);

