#define TCS34725_ADDRESS 0x29
#define TCS34725_REG_STATUS 0x00
#define TCS34725_REG_DATA 0x01

int read_tcs34725(int file_descriptor) {
    unsigned char data[2];
    int ret;

    ret = read(file_descriptor, data, 2);
    if (ret != 2) {
        perror("Failed to read from TCS34725");
        return -1;
    }

    // TCS34725 status byte (LSB first)
    unsigned char status = data[0];

    // TCS34725 data byte
    unsigned char data_value = data[1];

    printf("Red: %d, Green: %d, Blue: %d\n", data_value & 0b00001111, data_value & 0b00110000, data_value & 0b01111111);

    return 0;
}

int main(int argc, char *argv[]) {
    int file_descriptor, ret;
    struct i2c_client client;

    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    client.file = file_descriptor;
    client.address = TCS34725_ADDRESS;

    ret = ioctl(file_descriptor, I2C_SLAVE, &client);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_tcs34725(file_descriptor);
        usleep(500000); // 0.5 seconds delay
    }

    close(file_descriptor);
    return 0;
}

