    ret = pigpioInit(5); // 5 is the number of available pins
    if (ret < 0) {
        fprintf(stderr, "pigpioInit failed: %s\n", pi_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins as output
    for (int i = 0; i < gpio_count; i++) {
        gpio_pins[i] = GPIO_PINS[i];
        pigpioSetMode(gpio_pins[i], PIGIO_OUTPUT);
    }

    while (1) {
        // Generate PWM signal
        for (int i = 0; i < gpio_count; i++) {
            pigpioSetPWMfreq(gpio_pins[i], 1000); // Frequency in Hz
            pigpioPWM(gpio_pins[i], 0, 128); // 0-255 duty cycle
        }

        // Report the state
        for (int i = 0; i < gpio_count; i++) {
            int state = pigpioGet(gpio_pins[i]);
            printf("GPIO %d: %d\n", gpio_pins[i] + 1, state);
        }

        // Sleep for the specified delay
        usleep(DELAY_SECONDS * 1000000);
    }

    // Clean up and exit
    pigpioTerminate();
    return EXIT_SUCCESS;
}

