    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = tcgetattr(fd, &oldoptions);
    if (ret == -1) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    options = oldoptions;
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    ret = tcsetattr(fd, TCSANOW, &options);
    if (ret == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = read(fd, buffer, BUFSIZE);
        if (ret == -1) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        if (ret == 0) {
            printf("Device not present\n");
            exit(EXIT_FAILURE);
        }

        printf("%.*s\n", (int)ret, buffer);

        usleep(100000); // 0.1 seconds delay
    }

