#include <stdlib.h>
#include <libgpiod.h>

#define HC_SR04_ECHO_PIN 24
#define HC_SR04_TRIG_PIN 18
#define HC_SR04_SCLK_PIN 23

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, HC_SR04_TRIG_PIN, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    ret = gpiod_button_init(&button, &ctx);
    if (ret < 0) {
        perror("Failed to initialize button");
        gpiod_destroy_context(&ctx);
        return EXIT_FAILURE;
    }

    printf("Press trigger pin to measure distance...\n");

    while (1) {
        ret = gpiod_get_value(&button, &ret);
        if (ret < 0) {
            perror("Failed to read button state");
            break;
        }

        if (ret) {
            // Trigger pin is high, start measurement
            gpiod_button_release(&button);

            // Set trigger high
            gpiod_gpio_set_value(HC_SR04_TRIG_PIN, 1);

            // Wait for echo
            for (int i = 0; i < 1000; i++) {
                ret = gpiod_get_value(&button, &ret);
                if (ret < 0) {
                    perror("Failed to read button state");
                    break;
                }
                if (ret) {
                    // Trigger is still high, continue waiting
                    continue;
                }
            }

            // Measure distance
            ret = gpiod_gpio_get_value(HC_SR04_ECHO_PIN);
            if (ret < 0) {
                perror("Failed to read echo pin value");
                break;
            }

            // Convert pulse-in to distance (in cm)
            unsigned int duration = ret;
            unsigned long frequency = 55000UL; // Ultrasonic frequency
            unsigned long period = (unsigned long)duration * frequency / 2;
            double distance = (period / 2) * 100; // Convert to cm

            printf("Distance: %.2f cm\n", distance);

            // Release button
            gpiod_button_release(&button);
        }

        // Release button
        gpiod_button_release(&button);

        // Sleep for a short time to avoid busy-waiting
        usleep(10000);
    }

    // Release resources
    gpiod_destroy_button(&button);
    gpiod_destroy_context(&ctx);

    return EXIT_SUCCESS;
}

