#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO 18
#define FREQ 500  // PWM frequency in Hz
#define DUTY_CYCLE 100  // Duty cycle as a percentage (0-100)

void signal_handler(int signum) {
    printf("Received signal, exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

int main() {
    int ret;

    // Initialize pigpio
    ret = pigpioInit(5);  // 5 is the number of available pins
    if (ret < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Set up PWM on GPIO 18
    ret = pigpioSetupOutput(GPIO);
    if (ret < 0) {
        perror("Failed to set up GPIO 18 as output");
        pigpioExit();
        exit(EXIT_FAILURE);
    }

    // Set PWM frequency and duty cycle
    ret = pigpioSetPWMfreq(GPIO, FREQ);
    if (ret < 0) {
        perror("Failed to set PWM frequency");
        pigpioExit();
        exit(EXIT_FAILURE);
    }
    ret = pigpioSetPWM(GPIO, 0, DUTY_CYCLE);
    if (ret < 0) {
        perror("Failed to set PWM duty cycle");
        pigpioExit();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        printf("PWM state: %d\n", pigpioGetPWMState(GPIO));
        usleep(200000);  // Wait for 0.2 seconds
    }

    // Clean up and exit
    pigpioExit();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod/gpio.h>

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_context_init(&ctx);
    if (ret < 0) {
        perror("Failed to initialize gpiod context");
        return EXIT_FAILURE;
    }

    ret = gpiod_button_init(&ctx, GPIO_PIN_17, GPIO_DIR_OUTPUT, "button1");
    if (ret < 0) {
        perror("Failed to initialize button GPIO_PIN_17");
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    printf("Button 1 (GPIO 17) initialized as output.\n");

    // Simulate button press
    button.value = 1;
    ret = gpiod_button_write(&ctx, &button);
    if (ret < 0) {
        perror("Failed to write to button GPIO_PIN_17");
        gpiod_button_destroy(&ctx, &button);
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    printf("Button 1 (GPIO 17) set to HIGH.\n");

    // Wait for a short duration to observe the state change
    sleep(1);

    // Simulate button release
    button.value = 0;
    ret = gpiod_button_write(&ctx, &button);
    if (ret < 0) {
        perror("Failed to write to button GPIO_PIN_17");
        gpiod_button_destroy(&ctx, &button);
        gpiod_context_destroy(&ctx);
        return EXIT_FAILURE;
    }

    printf("Button 1 (GPIO 17) set to LOW.\n");

    gpiod_button_destroy(&ctx, &button);
    gpiod_context_destroy(&ctx);

    printf("Program exiting.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define GPIO_PIN2 23
#define GPIO_PIN3 24

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, GPIO_PIN, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    ret = gpiod_button_init(&button, &ctx);
    if (ret < 0) {
        perror("Failed to initialize button");
        gpiod_destroy_context(&ctx);
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_get_value(&button, &ctx);
        if (ret < 0) {
            perror("Failed to get button state");
            break;
        }

        if (ret) {
            printf("GPIO %d is HIGH\n", GPIO_PIN);
        } else {
            printf("GPIO %d is LOW\n", GPIO_PIN);
        }

        gpiod_button_deinit(&button, &ctx);
        gpiod_context_sleep(&ctx, GPIOD_FOREVER);
    }

    gpiod_destroy_context(&ctx);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68

typedef struct {
    int x;
    int y;
    int z;
    int t;
} mpu_data_t;

int main(int argc, char *argv[]) {
    int file;
    mpu_data_t data;
    char buffer[6];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <MPU6050 I2C address>\n", argv[0]);
        exit(1);
    }

    file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-" I2C_BUS);
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, (u_int8_t) atoi(argv[1])) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(1);
    }

    while (1) {
        if (read(file, buffer, 6) == -1) {
            perror("read from i2c");
            break;
        }

        data.x = (buffer[0] << 8) | read(file, &data.x, 1);
        data.y = (buffer[1] << 8) | read(file, &data.y, 1);
        data.z = (buffer[2] << 8) | read(file, &data.z, 1);
        data.t = (buffer[3] << 8) | read(file, &data.t, 1);

        printf("Accel: x=%d, y=%d, z=%d m/s^2\n", data.x, data.y, data.z);

        usleep(1000000); // Sleep for 1 second
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define GPIO_NUMBER 17
#define DELAY_SECONDS 0.6

int main(int argc, char *argv[]) {
    int ret;
    gpiod_context_t ctx;
    gpiod_button_t button;

    ret = gpiod_new_button(&ctx, GPIO_NUMBER, GPIOD_INPUT);
    if (ret < 0) {
        perror("Failed to create button");
        return EXIT_FAILURE;
    }

    gpiod_button_init(&button, &ctx);

    while (1) {
        ret = gpiod_get_value(&button);
        if (ret < 0) {
            perror("Failed to read button state");
            break;
        }

        if (ret) {
            printf("Button pressed\n");
        } else {
            printf("Button released\n");
        }

        gpiod_button_deinit(&button);
        gpiod_context_sleep(ctx, 1000000 / DELAY_SECONDS); // Sleep for the desired delay
    }

    gpiod_button_free(&button, &ctx);

    return EXIT_SUCCESS;
}
